"""Editable v0.1 glyph design. Coordinates use a 1000-unit square, y down."""
import math

WIDTH = 46

def line(*pts): return {'points': pts, 'width': WIDTH}
def q(a,b,c,n=24):
    return [( (1-t)**2*a[0]+2*(1-t)*t*b[0]+t*t*c[0], (1-t)**2*a[1]+2*(1-t)*t*b[1]+t*t*c[1]) for t in [i/n for i in range(n+1)]]
def curve(a,b,c): return line(*q(a,b,c))
def oval(cx,cy,rx,ry):
    return line(*[(cx+rx*math.cos(i*math.tau/64),cy+ry*math.sin(i*math.tau/64)) for i in range(65)])
def box(x,y,w,h):
    r=min(110,w/3,h/3)
    pts=[(x+r,y),(x+w-r,y)]+q((x+w-r,y),(x+w,y),(x+w,y+r))+[(x+w,y+h-r)]+q((x+w,y+h-r),(x+w,y+h),(x+w-r,y+h))+[(x+r,y+h)]+q((x+r,y+h),(x,y+h),(x,y+h-r))+[(x,y+r)]+q((x,y+r),(x,y),(x+r,y))
    return line(*pts)
def eyes(x,y,gap=80): return [{'dot': [x-gap/2,y], 'radius':16},{'dot':[x+gap/2,y-8],'radius':16}]
def face(x,y,gap=80): return eyes(x,y,gap)+[{'points':q((x-40,y+42),(x,y+78),(x+42,y+38)), 'width':25}]

